50	      include: { assignments: true },
51	      take: PAGE_SIZE,
52	      skip: (page - 1) * PAGE_SIZE,
53	    }),
54	    db.sizeChart.count({ where: { shop } }),
55	    db.subscription.findUnique({ where: { shop } }),
56	  ]);
57	
58	  const plan = getPlan(subscription?.planId ?? "free");
59	  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
60	    name: t.name,
61	    category: t.category,
62	    gender: t.gender,
63	    rowCount: t.data.rows.length,
64	  }));
65	  const categories = getCategories();
66	
67	  return {
68	    charts,
69	    totalCount,
70	    page,
71	    plan,
72	    templates,
73	    categories,
74	    canCreate: canCreateChart(plan.id, totalCount),
75	  };
76	};
