223	          where: { id: assignmentId, shop },
224	        });
225	        return { ok: true, message: "Assignment removed" };
226	      }
227	
228	      case "delete": {
229	        await db.sizeChart.deleteMany({ where: { id, shop } });
230	        return redirect("/app/size-charts");
231	      }
232	
233	      default:
234	        return { error: "Unknown action" };
235	    }
236	  } catch (error) {
237	    const message =
238	      error instanceof Error ? error.message : "An unexpected error occurred";
239	    if (message.includes("Unique constraint")) {
240	      return { error: "A chart with this name already exists." };
241	    }
242	    return { error: message };
243	  }
